<?php
declare(strict_types=1);require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';require_permission('billing.view');
$pageTitle='Servicios activos y renovaciones';$pdo=db();$filter=(string)($_GET['filter']??'all');$currency=(string)($_GET['currency']??'');$q=trim((string)($_GET['q']??''));
$all=$pdo->query("SELECT s.* FROM client_services s WHERE s.status='active'")->fetchAll();foreach($all as$r)billing_sync_charge($r);if(db_table_exists('billing_charges'))$pdo->exec("UPDATE billing_charges SET status='overdue' WHERE status='pending' AND due_date<CURDATE()");
$where=["s.status='active'"];$params=[];
if($filter==='monthly')$where[]="s.contract_type='monthly'";elseif($filter==='annual')$where[]="s.contract_type='annual'";elseif($filter==='one_time')$where[]="s.contract_type='one_time'";elseif($filter==='due7')$where[]="COALESCE(s.next_billing_date,s.expiration_date) BETWEEN CURDATE() AND DATE_ADD(CURDATE(),INTERVAL 7 DAY)";elseif($filter==='due30')$where[]="COALESCE(s.next_billing_date,s.expiration_date) BETWEEN CURDATE() AND DATE_ADD(CURDATE(),INTERVAL 30 DAY)";elseif($filter==='overdue')$where[]="EXISTS(SELECT 1 FROM billing_charges bc WHERE bc.service_id=s.id AND bc.status='overdue')";elseif($filter==='paid')$where[]="s.billing_status='paid'";
if(in_array($currency,['CLP','USD','BRL'],true)){$where[]='s.currency=?';$params[]=$currency;}if($q!==''){$where[]='(c.company_name LIKE ? OR s.name LIKE ?)';$like='%'.$q.'%';array_push($params,$like,$like);}
$sql="SELECT s.*,c.company_name,c.country,bc.id charge_id,bc.status charge_status,bc.due_date charge_due FROM client_services s JOIN clients c ON c.id=s.client_id LEFT JOIN billing_charges bc ON bc.service_id=s.id AND bc.due_date=COALESCE(s.next_billing_date,s.expiration_date) WHERE ".implode(' AND ',$where)." ORDER BY COALESCE(s.next_billing_date,s.expiration_date) IS NULL,COALESCE(s.next_billing_date,s.expiration_date),c.company_name";$st=$pdo->prepare($sql);$st->execute($params);$rows=$st->fetchAll();
require __DIR__.'/includes/header.php';?>
<section class="panel"><div class="panel-header"><div><h2>Servicios facturables</h2><span class="table-sub">Negocios cerrados, mensualidades, renovaciones anuales y pagos únicos.</span></div><div class="actions"><a class="btn btn-secondary" href="billing.php">RESUMEN</a><?php if(has_permission('services.assign')):?><a class="btn btn-primary" href="service_form.php">+ SERVICIO ACTIVO</a><?php endif;?></div></div><form class="panel-body filters-bar" method="get"><input name="q" value="<?=e($q)?>" placeholder="Cliente o servicio"><select name="filter"><option value="all">Todos</option><?php foreach(['monthly'=>'Mensuales','annual'=>'Anuales','one_time'=>'Pago único','due7'=>'Próximos 7 días','due30'=>'Próximos 30 días','overdue'=>'Vencidos','paid'=>'Pagados']as$k=>$l):?><option value="<?=$k?>" <?=$filter===$k?'selected':''?>><?=$l?></option><?php endforeach;?></select><select name="currency"><option value="">Todas las monedas</option><?php foreach(['CLP','USD','BRL']as$c):?><option <?=$currency===$c?'selected':''?>><?=$c?></option><?php endforeach;?></select><button class="btn btn-secondary">FILTRAR</button></form><div class="table-wrap"><table class="data-table"><thead><tr><th>Cliente</th><th>Servicio</th><th>Modalidad</th><th>Próximo cobro</th><th>Valor</th><th>Pago</th><th>Estado servicio</th><th></th></tr></thead><tbody><?php foreach($rows as$r):$bs=$r['charge_status']?:($r['billing_status']?:'pending');?><tr><td><a class="table-title" href="client_view.php?id=<?=(int)$r['client_id']?>"><?=e($r['company_name'])?></a><span class="table-sub"><?=e($r['country']?:'')?></span></td><td><strong><?=e($r['name'])?></strong></td><td><?=e(contract_label($r['contract_type']))?></td><td><?=e(format_date($r['next_billing_date']?:$r['expiration_date']))?></td><td><?=e(format_money($r['amount'],$r['currency']))?></td><td><span class="badge badge-<?=e(billing_status_class($bs))?>"><?=e(billing_status_label($bs))?></span></td><td><span class="badge badge-green"><?=e(client_status_label($r['status']))?></span></td><td><div class="actions"><?php if($r['charge_id']&&$bs!=='paid'&&has_permission('payments.manage')):?><a class="btn btn-primary btn-small" href="billing_charge_pay.php?id=<?=(int)$r['charge_id']?>">PAGAR</a><?php endif;?><?php if(has_permission('services.edit')):?><a class="btn btn-light btn-small" href="service_form.php?id=<?=(int)$r['id']?>">EDITAR</a><?php endif;?></div></td></tr><?php endforeach;?></tbody></table><?php if(!$rows):?><div class="empty">No hay servicios con estos filtros.</div><?php endif;?></div></section>
<?php require __DIR__.'/includes/footer.php';?>
